import React, { useEffect, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import {
  fetchUsersAsync,
  selectUsersState,
  updateUserAsync,
  deleteUserAsync,
} from "./userSlice";
import "./UserList.css";

function UserList() {
  const dispatch = useDispatch();
  const { users, loading, error } = useSelector(selectUsersState);

  const [editUserId, setEditUserId] = useState(null);
  const [editData, setEditData] = useState({});

  useEffect(() => {
    dispatch(fetchUsersAsync());
  }, [dispatch]);

  const handleEditClick = (user) => {
    setEditUserId(user.id);
    setEditData({ ...user, profile: { ...user.profile } });
  };

  const handleChange = (key, value) => {
    if (key === "bio" || key === "phone") {
      setEditData({
        ...editData,
        profile: { ...editData.profile, [key]: value },
      });
    } else {
      setEditData({ ...editData, [key]: value });
    }
  };

  const handleSave = () => {
    dispatch(updateUserAsync(editData));
    setEditUserId(null);
  };

  const handleCancel = () => {
    setEditUserId(null);
  };

  const handleDelete = (id) => {
    if (window.confirm("Are you sure you want to delete this user?")) {
      dispatch(deleteUserAsync(id));
    }
  };

  if (loading) return <p>Loading users...</p>;
  if (error) return <p className="error-text">Error: {error}</p>;

  return (
    <div className="userlist-container">
      <h2>User Management</h2>
      <table className="user-table">
        <thead>
          <tr>
            <th>ID</th>
            <th>Username</th>
            <th>Email</th>
            <th>Bio</th>
            <th>Phone</th>
            <th>Status</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {users.length > 0 ? (
            users.map((u) => (
              <tr key={u.id}>
                <td>{u.id}</td>
                <td>
                  {editUserId === u.id ? (
                    <input
                      type="text"
                      value={editData.username}
                      onChange={(e) =>
                        handleChange("username", e.target.value)
                      }
                    />
                  ) : (
                    u.username
                  )}
                </td>
                <td>
                  {editUserId === u.id ? (
                    <input
                      type="text"
                      value={editData.email}
                      onChange={(e) =>
                        handleChange("email", e.target.value)
                      }
                    />
                  ) : (
                    u.email
                  )}
                </td>
                <td>
                  {editUserId === u.id ? (
                    <input
                      type="text"
                      value={editData.profile?.bio || ""}
                      onChange={(e) => handleChange("bio", e.target.value)}
                    />
                  ) : (
                    u.profile?.bio || ""
                  )}
                </td>
                <td>
                  {editUserId === u.id ? (
                    <input
                      type="text"
                      value={editData.profile?.phone || ""}
                      onChange={(e) => handleChange("phone", e.target.value)}
                    />
                  ) : (
                    u.profile?.phone || ""
                  )}
                </td>
                <td>
                  {editUserId === u.id ? (
                    <select
                      value={editData.is_active ? "Active" : "Inactive"}
                      onChange={(e) =>
                        handleChange("is_active", e.target.value === "Active")
                      }
                    >
                      <option>Active</option>
                      <option>Inactive</option>
                    </select>
                  ) : u.is_active ? (
                    "Active"
                  ) : (
                    "Inactive"
                  )}
                </td>
                <td>
                  {editUserId === u.id ? (
                    <>
                      <button className="save-btn" onClick={handleSave}>
                        Save
                      </button>
                      <button className="cancel-btn" onClick={handleCancel}>
                        Cancel
                      </button>
                    </>
                  ) : (
                    <>
                      <button
                        className="edit-btn"
                        onClick={() => handleEditClick(u)}
                      >
                        Edit
                      </button>
                      <button
                        className="delete-btn"
                        onClick={() => handleDelete(u.id)}
                      >
                        Delete
                      </button>
                    </>
                  )}
                </td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan="7" style={{ textAlign: "center" }}>
                No users found
              </td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
}

export default UserList;
